// metal: a two-operator FM exciter that drops onto each note, into a six-mode MODAL resonator whose modes sit at
// the material's ratios (the first below the note), STRETCH spreading or squeezing them, RATIO free, and make-up as the
// reference sets it (modes off the FM's harmonic lattice boosted). A fixed-point port of the float reference engine
// (rings.c in the port kit), with its constants (tables.h, generated by tools/gen_tables.py), simplified for the
// OP-XY's CPU.
//
// The voice runs at half the output rate, 22.05 kHz (the voice rate, VR): the FM core and the modes have nothing above
// 11 kHz (the core's output is 70 dB down there at every setting), so only the last stage runs at 44.1 kHz.
// Per 64-sample block, 32 voice samples:
//   FM core, in four 8-sample steps (the drop, BITE and the onset move per step, as in the reference's 16-sample
//     sub-block); op2 and its one-poles at the voice rate, the carrier's phase stepping two output samples at a time;
//     sines read from a table without interpolation
//   -> the chain's high-pass on the drive
//   -> MODAL: up to six undamped two-pole oscillators, damped every step (+ STRIKE). Modes below VR/4 (5.5 kHz) are
//      fed once per two voice samples, the others every sample
//   -> mix: core + modes -> both fixed 20.7 kHz low-passes as one 3-tap FIR -> the chain's band, which carries every
//      output gain
//   -> to 44.1 kHz: a polyphase IIR half-band (four first-order allpasses) -> half-scale ceiling
//
// The chain: the reference's two keytracked high-passes, presence peak and high shelf (sixth order) are fitted as two
// biquads in units of the note (tools/gen_tables.py, CHAIN; within 1.4 dB from 0.2 x the note): a resonant high-pass,
// which shapes the drive as the reference's first high-pass and presence peak do, and a band after the modes. The
// reference's STRIKE skips the filters before the modes; here it is rotated per mode by the gain it misses.
//
// The OP-XY gives a voice no note-off, so the stock amp envelope shapes the whole sound: the voice runs as the
// reference does at ATTACK 0 and SUSTAIN 1, struck at full strength. It keeps the reference's 3 ms eased onset.
//
// Fixed point throughout: Q31 signals, coefficients made per note and per knob change from table-based sine, log2
// and exp2 (fixmath.h). No float, no division and no 64-bit arithmetic in the audio path. Recursive filters and the
// low modes keep the small quantities near their poles as their coefficients (2 + a1, 1 - a2, 2 - 2 cos th), so low
// notes keep their precision. Signed right shifts are arithmetic (GCC and Clang define them so).
// Where a voice struck again and again would carry a sum past the 32-bit range, it saturates instead of wrapping, and
// everything else is as exact as before (the mix's two passes, hot modes, band, fir_tail, ceiling2; README: Overflow).
#include "core.h"
#include "fixmath.h"

namespace metal {
namespace {

const unsigned VN = opxy::block_frames / 2;   // voice samples per block
const unsigned STEP = 8;                       // voice samples per step: the reference's 16-sample sub-block
const unsigned STEPS = VN / STEP;
const u32 CHAIN_TOP = 660000000u;             // 6.78 kHz as an increment: the chain's highest note (setup_pitch)
const i32 HOT = 0x66666666;                    // a mode this loud (0.8 of full scale) runs held (hot)

inline i32 knob_word(i32 w) { return w < 0 ? 0 : w; }
// sin from the 4096-point Q15 table, no interpolation, scaled to Q(15 + s).
template <int S> inline i32 sin16(u32 phase) { return static_cast<i32>(SINE16[phase >> 20]) * (1 << S); }

// ---------------------------------------------------------------- filters
// The half angle of a cutoff given as a phase increment (2^32 = the sample rate): h = sin(w0/2), k = cos(w0/2), Q31.
inline void half_angle(u32 inc, i32& h, i32& k) {
    h = sine(inc >> 1) * 2;
    k = cosine(inc >> 1) * 2;
}
// The chain, both keytracked high-passes, the presence peak and the shelf, as two biquads fitted in units of the note
// (tools/gen_tables.py, CHAIN): a high-pass s^2 / (s^2 + a1 s + a0) and a band s (b2 s + b1) / (s^2 + c1 s + c0), made
// digital per note by the bilinear transform warped at the note, u = tan(pi f0 / fs). With z = z^-1 and
// D = 1 + a1 u + a0 u^2, a pole pair is 2 + a1' = 2 (a1 u + 2 a0 u^2) / D and 1 - a2' = 2 a1 u / D (each a product, from
// logs: no cancellation at low notes, where u is tiny). The high-pass runs as (1 - z)^2 without its 1 / D; the band's
// numerator, (b2 (1 - z)^2 + b1 u (1 - z^2)) / D, carries that, the output gain and a 2 for the half sums it takes.
// ch_c: high-pass 2 + a1' (Q30), 1 - a2' (Q31); band b2 and b1 u terms (Q27), 2 + a1' (Q29), 1 - a2' (Q31).
__attribute__((noinline)) void setup_chain(Voice& v, u32 inc) {
    i32 h, c; half_angle(inc, h, c);
    const i32 lu = log2q(h, 31) - log2q(c, 31), one = 1 << 27;
    const i32 p1 = exp2q(L_CH_A1 + lu, 27), p2 = exp2q(L_CH_A0 + 2 * lu, 27);
    const i32 ld1 = log2q(one + p1 + p2, 27);
    v.ch_c[0] = exp2q(ONE_LOG + lu + log2q(exp2q(L_CH_A1, 27) + exp2q(L_CH_A0 + lu + ONE_LOG, 27), 27) - ld1, 30);   // 2u (a1 + 2 a0 u) / D
    v.ch_c[1] = exp2q(ONE_LOG + L_CH_A1 + lu - ld1, 31);
    const i32 q1 = exp2q(L_CH_C1 + lu, 25), q2 = exp2q(L_CH_C0 + 2 * lu, 25);   // Q25: up to the top notes at the voice rate
    const i32 ld2 = log2q((1 << 25) + q1 + q2, 25), lg = L_OUT - ld1 - ld2 + ONE_LOG;
    v.ch_c[2] = exp2q(L_CH_B2 + lg, 27);
    v.ch_c[3] = exp2q(L_CH_B1 + lu + lg, 27);
    v.ch_c[4] = exp2q(ONE_LOG + lu + log2q(exp2q(L_CH_C1, 25) + exp2q(L_CH_C0 + lu + ONE_LOG, 25), 25) - ld2, 29);
    v.ch_c[5] = exp2q(ONE_LOG + L_CH_C1 + lu - ld2, 31);
}

// ---------------------------------------------------------------- knobs
// A DROP lane: 0..1 along it, split at DROP_SPLIT, each side a power curve.
i32 lane(i32 x, i32 mid, i32 e1, i32 e2) {
    if (x <= DROP_SPLIT_Q31) {
        const i32 y = clamp(mul29(x, DROP_SPLIT_INV), 0, MAX);
        return y ? mul(mid, exp2q(mul29(log2q(y, 31), e1), 31)) : 0;
    }
    const i32 y = clamp(mul29(x - DROP_SPLIT_Q31, DROP_HI_INV), 0, MAX);
    return mid + mul(MAX - mid, y ? exp2q(mul29(log2q(y, 31), e2), 31) : 0);
}
// The OP-XY shows each knob 0..99. DROP's 25 is where the sweep is none: 0..25 covers the lanes up to their own zero
// (DROP_ZERO, about 17) and 25..99 the rest, both linearly.
inline i32 drop_lanes(i32 knob) {
    if (knob <= DROP_KNOB_25) return mul(knob, DROP_SKEW_LO);
    const i32 up = mul29(knob - DROP_KNOB_25, DROP_SKEW_HI);
    return up >= MAX - DROP_ZERO ? MAX : DROP_ZERO + up;
}
// RATIO shows its value / 100 at 0..98 of 0..99, and 1.00 at 99.
inline i32 ratio_of(i32 knob) {
    if (knob <= RATIO_KNOB_98) return mul(knob, RATIO_LO);
    const i32 up = mul29(knob - RATIO_KNOB_98, RATIO_HI);
    return up >= MAX - RATIO_98 ? MAX : RATIO_98 + up;
}
__attribute__((noinline)) void set_drop(Voice& v, i32 knob) {
    const i32 x = drop_lanes(knob);
    i32 oct = SW_A0 + mul(SW_SPAN, lane(x, SW_MID, SW_E1, SW_E2));
    if (absolute(oct) < SW_DEAD) oct = 0;
    v.sweep_oct = oct;
    v.sweep_du = exp2q(L_DT_T0 - mul(L_T1_T0, lane(x, TM_MID, TM_E1, TM_E2)), 31);
}
// STRETCH as the reference: each mode at its material ratio, log2 scaled by 2^(2 x - 1) (ratio^1/2 .. ratio^2), plus
// its fixed detune.
__attribute__((noinline)) void set_stretch(Voice& v, i32 x) {
    const i32 centred = x - 0x40000000;
    const i32 stretch = absolute(centred) < STRETCH_DEAD ? 0 : sar(centred, 6);   // 2 (x - 0.5), Q24
    const i32 st = exp2q(stretch, 29);                                           // 2^stretch, Q29
    for (unsigned k = 0; k < MODES; ++k) v.lrr[k] = mul29(L_RM[k], st) + L_SPREAD[k];
}
__attribute__((noinline)) void set_modes(Voice& v, i32 x) {
    const i32 m5 = mul(x, static_cast<i32>(MODES - 1) << 28);   // 5 x, Q28: mode k is fed clamp(1 + 5x - k, 0, 1)
    v.wk[0] = MAX;
    for (unsigned k = 1; k < MODES; ++k) {
        const i32 w = clamp(m5 - static_cast<i32>(k - 1) * (1 << 28), 0, 1 << 28);
        v.wk[k] = w == (1 << 28) ? MAX : w * 8;
    }
}

// ---------------------------------------------------------------- note set-up
// Keytracked filters for a pitch.
void setup_pitch(Voice& v, u32 inc) {
    v.setup_inc = inc;
    v.linc = log2u(inc) + ONE_LOG;                    // the note as a voice-rate increment
    // Warped at the voice rate. From 6.79 kHz a sum in setup_chain would leave the 32-bit range (and from about 7.8 kHz
    // the band's poles the unit circle): the chain stays at 6.78 kHz's.
    setup_chain(v, 2u * (inc < CHAIN_TOP ? inc : CHAIN_TOP));
}
// Where the modes sit: frequency (as a voice-rate increment), edge fade, oscillator coefficient and feed, for the pitch
// and STRETCH. The modes run undamped per voice sample; their decay is applied every step (DAMP16).
__attribute__((noinline)) void setup_modes(Voice& v) {
    const i32 linc = v.linc;
    v.high = 0;
    v.pair = 0;
    for (unsigned k = 0; k < MODES; ++k) {
        const i32 l = linc + v.lrr[k];
        v.lfk[k] = clamp(l, L_INC_20HZ, L_INC_NY);
        i32 edge = 0;
        u32 fk = 0;
        if (l < L_INC_NY) {
            fk = exp2u(l);                              // below the top here: no overflow
            if (fk > static_cast<u32>(INC_20HZ)) {
                edge = fk < 2u * static_cast<u32>(INC_20HZ)
                    ? exp2q(log2u(fk - static_cast<u32>(INC_20HZ)) - L_INC_20HZ, 31) : MAX;
                if (l > L_INC_NY09)
                    edge = mul(edge, exp2q(log2u(static_cast<u32>(INC_LIMIT) - fk) - L_INC_NY01, 31));
            }
        }
        v.edge[k] = edge;
        if (!edge) { v.y1[k] = v.y2[k] = 0; v.mc[k] = 0; v.sn[k] = 0; v.lsn[k] = 0; continue; }
        i32 h, c; half_angle(fk, h, c);
        const i32 sn = 2 * mul(h, c);                   // sin th
        v.sn[k] = sn;
        const i32 hs = mul(sn, HOT) >> 1;                 // hot's limit: (HOT sin th / 2)^2
        v.lim[k] = mul(hs, hs);
        v.lch[k] = log2q(c, 31);                        // log2 cos(th / 2)
        if (fk < static_cast<u32>(INC_QUARTER)) v.pair |= 1u << k;
        if (fk < static_cast<u32>(INC_SIXTH)) {
            v.mc[k] = mul(h, h) * 4;                    // 2 - 2 cos th = 4 sin^2(th / 2), Q31
        } else {
            v.mc[k] = cosine(fk) * 2;                   // 2 cos th, Q30
            v.high |= 1u << k;
        }
        const i32 lsn = log2q(sn, 31);
        v.lsn[k] = lsn;
        v.leps[k] = sar(softplus2(L_EPS[k] - 2 * lsn), 1);
        const i32 c1 = cosine(fk);
        v.rc[k] = c1 >= 0x40000000 ? MAX : c1 * 2;     // cos th, Q31
        // STRIKE's correction, 1 / (HP PK) at the mode's ratio to the note: tables in 1/16 octaves from 2^-4
        const i32 pos = clamp(l - linc + 4 * ONE_LOG, 0, 10 * ONE_LOG - 1);
        const i32 at = pos >> 20, frac = (pos & 0xfffff) << 11;
        v.gre[k] = STRIKE_GRE[at] + mul(STRIKE_GRE[at + 1] - STRIKE_GRE[at], frac);
        v.gim[k] = STRIKE_GIM[at] + mul(STRIKE_GIM[at + 1] - STRIKE_GIM[at], frac);
    }
}
// |d| folded onto the FM lattice spacing sp (lsp its log2): distance to the nearest lattice line (Q26).
i32 fold(i32 d, i32 sp, i32 lsp) {
    if (d >= sp) {
        const u32 n = exp2u(log2u(static_cast<u32>(d)) - lsp);
        d = static_cast<i32>(static_cast<u32>(d) - n * static_cast<u32>(sp));
        if (d < 0) d += sp;
        if (d >= sp) d -= sp;
    }
    return 2 * d > sp ? sp - d : d;
}
// log2(1 + X^2), X = 2 d f0 / bw: how far a mode at distance d (ld = log2 d, d Q26 in notes; NO_LOG for 0) sits off
// the lattice, in bandwidths.
const i32 NO_LOG = -128 * ONE_LOG;
inline i32 off_lattice(i32 ld, i32 lhz, i32 lbw) {
    return ld != NO_LOG ? softplus2(2 * (ONE_LOG + ld + lhz - lbw)) : 0;
}
// Make-up gain per mode, as the reference: modes moved off the FM's harmonic lattice catch less of it (at most 18 dB
// either way), and modes moved up get up to 12 dB more, (ratio)^0.75.
// The lattice spacing for RATIO, and each material ratio folded onto it (per RATIO change, not per note).
__attribute__((noinline)) void set_ratio(Voice& v, i32 ratio_word) {
    v.sp = (ratio_word > RATIO_MIN ? ratio_word : MAX) >> 5;   // Q26
    v.lsp = log2u(static_cast<u32>(v.sp));
    for (unsigned k = 0; k < MODES; ++k) {
        const i32 dm = fold(RM_DIST[k], v.sp, v.lsp);
        v.ldm[k] = dm ? log2q(dm, 26) : NO_LOG;
    }
}
__attribute__((noinline)) void setup_makeup(Voice& v) {
    const i32 linc = v.linc;                           // voice-rate increments
    const i32 lhz = linc + L_FS - 32 * ONE_LOG;
    for (unsigned k = 0; k < MODES; ++k) {
        const u32 rel = exp2u(v.lfk[k] - linc + 26 * ONE_LOG);
        const i32 ratio_k = rel > 0x7fffffffu ? MAX : static_cast<i32>(rel);
        const i32 da = fold(absolute(ratio_k - (1 << 26)), v.sp, v.lsp);
        const i32 off = off_lattice(da ? log2q(da, 26) : NO_LOG, lhz, L_BW[k]) - off_lattice(v.ldm[k], lhz, L_BW[k]);
        i32 lmk = clamp(sar(off, 1), -3 * ONE_LOG, 3 * ONE_LOG);
        const i32 up = v.lfk[k] - linc - L_RM[k];
        if (up > 0) { const i32 t = mul(up, UP_POWER); lmk += t < 2 * ONE_LOG ? t : 2 * ONE_LOG; }
        v.mk_target[k] = exp2q(lmk, 25);
        if (!v.mk[k]) v.mk[k] = v.mk_target[k];
    }
    v.gx_dirty = 1;
}
// Each mode's input gain: the reference's b = (1 - r) |1 - r e^(2 j th)| ra RES_GAIN edge make-up MODES, in log2.
// Modes above VR/4 take the drive every voice sample. Below, it arrives once per two samples as the pair's sum, whose
// gain at the mode is cos(th / 2) per sample.
__attribute__((noinline)) void update_b(Voice& v) {
    for (unsigned k = 0; k < MODES; ++k) {
        i32 l = L_B[k] + v.lsn[k] + v.leps[k] + log2q(v.mk[k], 25);
        if ((v.pair >> k) & 1) l -= v.lch[k];
        v.b[k] = v.edge[k] && v.wk[k] ? mul(mul(exp2q(l, 31), v.edge[k]), v.wk[k]) : 0;
    }
    v.gx_dirty = 0;
}

// ---------------------------------------------------------------- the onset
// The reference's shortest attack: the level rises 3 ms in a straight line from where the note found it, eased in.
// Each stage applies its square root; returns the gain after this step.
i32 onset_step(Voice& v) {
    if (!v.ramping) return MAX;
    v.att_u = v.att_u >= MAX - ATTACK_STEP ? MAX : v.att_u + ATTACK_STEP;
    const u32 j = v.att_j++;
    const i32 w = j < sizeof EASE / sizeof EASE[0] ? EASE[j] : MAX;
    if (v.att_u == MAX && w == MAX) { v.ramping = 0; return MAX; }
    return v.att_g0 + mul(sqrt31(v.att_u) - v.att_g0, w);
}

// ---------------------------------------------------------------- FM core
// op2's depth stays below 2 (Q29), so the one-pole after it needs no clamp (core_step).
static_assert(DEPTH0 + DEPTH_BITE < (1 << 30), "op2's depth reaches 2");
// log2 of the pitch's increment, kept while the pitch holds.
inline i32 log2_base(Voice& v, u32 base) {
    if (base != v.lbase_inc || !base) { v.lbase_inc = base; v.lbase = log2u(base); }
    return v.lbase;
}
// One step (8 voice samples): op2 with self-feedback phase-modulates the carrier through two one-poles; the drop
// multiplies both increments. The reference runs this at 2x and decimates with a half-band; here it runs at the voice
// rate with the 2x rate's quantities: op2 and its one-poles step four reference samples at a time (its difference
// quartered, the one-poles at their coefficient for four, its feedback read where the 2x rate would read it), and the
// carrier steps two output samples, its increment gliding per output sample as before. Increments are 1x (output
// rate). Writes the reference's x.
void core_step(Voice& v, i32* x, u32 base, i32 ratio) {
    u32 inc0 = base;
    if (v.sweep_oct) {
        if (!v.sweep_u) {
            inc0 = exp2u(log2_base(v, base) + v.sweep_oct);   // nothing of the drop done yet
        } else if (v.sweep_u < MAX) {
            const i32 lu = log2q(v.sweep_u, 31);
            const i32 left = MAX - exp2q(lu + mul(lu, SWEEP_E), 31);   // 1 - u^e
            inc0 = exp2u(log2_base(v, base) + mul(v.sweep_oct, left));
        }
        if (inc0 > static_cast<u32>(INC_DROP_LIMIT)) inc0 = static_cast<u32>(INC_DROP_LIMIT);
        if (v.sweep_u < MAX) {                         // u = j du; the drop never takes more than 256 steps
            const u32 u = static_cast<u32>(v.sweep_du >> 4) * ++v.sweep_j;   // Q27
            v.sweep_u = u >= (1u << 27) || v.sweep_j >= 256 ? MAX : static_cast<i32>(u << 4);
        }
    }
    const u32 inc2 = static_cast<u32>(mul(static_cast<i32>(inc0 >> 1), ratio)) * 4u;   // op2, per voice sample
    const i32 depth = DEPTH0 + mul(DEPTH_BITE, v.bite);   // Q29
    v.bite = mul(v.bite, BITE_DECAY);
    const i32 diff = static_cast<i32>(inc0 - v.inc_prev);
    const u32 dinc = static_cast<u32>(diff >= 0 ? diff >> 4 : -((-diff) >> 4));   // per output sample
    // op2, its feedback read ahead (fb = s2 + 3/4 of its last step) and the two one-poles; x holds each sample's l2 for
    // the carrier below
    u32 ph2 = v.ph2;
    i32 s2p = v.s2p, fb = v.fb, l1 = v.l1, l2 = v.l2;
    for (unsigned k = 0; k < STEP; ++k) {
        ph2 += inc2;
        const i32 s2 = sin16<15>(ph2 + static_cast<u32>(mul(fb, FB_PHASE)));
        const i32 step = s2 - s2p;                     // |step| < 2^31
        const i32 d = step >> 2;
        fb = static_cast<i32>(static_cast<u32>(s2) + static_cast<u32>(step) - static_cast<u32>(d));
        s2p = s2;
        const i32 m = l1;
        l1 = d - ((d - l1) >> 4);                      // l1 / 16 + 15 d / 16
        x[k] = l2;
        // |m| < 2^29 and depth < 2 (Q29), so m depth stays inside +-2^30: no clamp
        const i32 dm = mul29(m, depth);
        l2 = dm - ((dm - l2) >> 4);
    }
    // The carrier steps two output samples per voice sample, its increment gliding by dinc each:
    // ph0 += 2 (inc + u) + 3 dinc and inc += 2 dinc, kept as q = 2 inc + 3 dinc (+ 4 dinc per voice sample);
    // u = 2 l2 (0.25 u cycles per 2x sample: u in Q30, per output sample).
    u32 q = 2u * v.inc_prev + 3u * dinc, ph0 = v.ph0;
    const u32 dq = 4u * dinc;
    for (unsigned k = 0; k < STEP; ++k) {
        const u32 w = q + 4u * static_cast<u32>(x[k]);
        x[k] = sin16<12>(ph0);                         // the carrier at 1/16 full scale: x = car / 2
        ph0 += w;
        q += dq;
    }
    v.ph0 = ph0; v.ph2 = ph2; v.s2p = s2p; v.fb = fb; v.l1 = l1; v.l2 = l2; v.inc_prev = inc0;
}

// ---------------------------------------------------------------- MODAL
// Modes run undamped: y = 2 cos th y1 - y2, plus the input (and STRIKE); their decay, r^8, is applied every step.
// HIGH modes keep 2 cos th in Q30; low ones keep 2 - 2 cos th in Q31.
struct Mode { i32 y1, y2, c, b, damp, lim; };
template <bool HIGH> inline i32 osc(i32 y1, i32 y2, i32 c) { return (HIGH ? mul30(y1, c) : 2 * y1 - mul(y1, c)) - y2; }
// The same plus an input v, saturated where it would leave the 32-bit range and exact everywhere else: struck again and
// again while it rings, a mode can build up past full scale. yc is y / 8 to within 4 below: over 2^30 either way, y has
// wrapped if its sign disagrees, and has surely wrapped past 3 2^30.
template <bool HIGH> inline i32 osc_held(i32 y1, i32 y2, i32 c, i32 v) {
    const i32 m = mul(y1, c);
    const i32 y = static_cast<i32>((HIGH ? 2u * static_cast<u32>(m) : 2u * static_cast<u32>(y1) - static_cast<u32>(m))
                                   - static_cast<u32>(y2) + static_cast<u32>(v));
    const i32 yc = (HIGH ? m >> 2 : (y1 >> 2) - (m >> 3)) - (y2 >> 3) + (v >> 3);
    if (yc > (1 << 27)) return yc >= (3 << 27) || y < 0 ? MAX : y;
    if (yc < -(1 << 27)) return yc < -(3 << 27) || y >= 0 ? -MAX : y;
    return y;
}
// Whether a mode could reach full scale within a step: its amplitude A at HOT or more, from the state:
// (A sin th / 2)^2 = ((y1 - y2)^2 + (2 - 2 cos th) y1 y2) / 4 (low modes; y1^2 + y2^2 - 2 cos th y1 y2 for high ones),
// against the mode's limit (setup_modes). A mode grows by under 3% of full scale a step (11% a block) and one note
// alone stays below 0.75, so a mode that is not hot cannot reach full scale before the next look.
template <bool HIGH> inline bool hot(const Mode& m) {
    const i32 a = m.y1 >> 1, b = m.y2 >> 1;
    const i32 q = HIGH ? mul(a, a) + mul(b, b) - mul30(mul(a, b), m.c) : mul(a - b, a - b) + mul(mul(a, b), m.c);
    return q > m.lim;
}

// floor(d / 32) + floor(d / 1024) for d = a - b, which itself would wrap: floor((a - b) / 2^k) is
// (a >> k) - (b >> k), less 1 where a's low k bits are below b's.
inline i32 fir_tail(i32 a, i32 b) {
    return (a >> 5) - (b >> 5) - ((a & 31) < (b & 31)) + (a >> 10) - (b >> 10) - ((a & 1023) < (b & 1023));
}

// The mix's accumulator. Adding a mode wraps where the 32-bit range ends, which leaves the sum exact as long as each
// sample's total is in range, whatever the partial sums did on the way. The first pass only notes whether a partial sum
// wrapped (rarely: a voice struck again and again); then a second pass counts each sample's wraps, and a sample whose
// count is not zero is out of range and saturates (process).
struct Note {                                          // the first pass
    i32 any;                                           // negative once a partial sum has wrapped
    // ov collects a step's wraps, kept in a register
    inline void add(i32* p, i32 y, i32& ov) const {
        const i32 a = *p, s = static_cast<i32>(static_cast<u32>(a) + static_cast<u32>(y));
        ov |= (a ^ s) & (y ^ s);
        *p = s;
    }
};
struct Count {                                         // the second
    i32 any;
    const i32* acc;
    i32* wraps;                                        // per sample: wraps up, less wraps down
    inline void add(i32* p, i32 y, i32&) const {
        const i32 a = *p, s = static_cast<i32>(static_cast<u32>(a) + static_cast<u32>(y));
        if (((a ^ s) & (y ^ s)) < 0) wraps[p - acc] += y < 0 ? -1 : 1;
        *p = s;
    }
};

// Modes above VR/4: the input every voice sample.
template <bool H, bool HOLD, class S>
inline void each_one_step(S& sum, i32* acc, const i32* in, Mode& m) {
    i32 y1 = m.y1, y2 = m.y2, ov = 0;
    for (unsigned n = 0; n < STEP; ++n) {
        const i32 y = HOLD ? osc_held<H>(y1, y2, m.c, mul(m.b, in[n])) : osc<H>(y1, y2, m.c) + mul(m.b, in[n]);
        sum.add(acc + n, y, ov);
        y2 = y1; y1 = y;
    }
    sum.any |= ov;
    m.y1 = mul(y1, m.damp); m.y2 = mul(y2, m.damp);
}
// Modes below VR/4: the input once per two voice samples, the pair's sum (in: STEP / 2 sums, acc: STEP samples).
template <bool H, bool HOLD, class S>
inline void one_step(S& sum, i32* acc, const i32* in, Mode& m) {
    i32 y1 = m.y1, y2 = m.y2, ov = 0;
    for (unsigned n = 0; n < STEP / 2; ++n) {
        const i32 y = HOLD ? osc_held<H>(y1, y2, m.c, mul(m.b, in[n])) : osc<H>(y1, y2, m.c) + mul(m.b, in[n]);
        const i32 z = HOLD ? osc_held<H>(y, y1, m.c, 0) : osc<H>(y, y1, m.c);
        sum.add(acc + 2 * n, y, ov); sum.add(acc + 2 * n + 1, z, ov);
        y2 = y; y1 = z;
    }
    sum.any |= ov;
    m.y1 = mul(y1, m.damp); m.y2 = mul(y2, m.damp);
}
// STRIKE, in the note's first step: the pulse rings through a separate copy of the mode, which joins the mode rotated
// by G = gre + j gim (setup_modes; the chain after the modes, against what STRIKE went through in the reference). For a
// ring A cos(w n + phi) held as (s1, s0) = (y[n], y[n-1]), Im = (s0 - cos w s1) / sin w and the rotated ring is
// s1' = gre s1 - gim Im, s0' = cos w s1' + gre (s0 - cos w s1) + gim sin w s1. The ring's own samples go out
// unrotated.
template <class S>
inline void strike_step(S& sum, i32* acc, bool high, i32 c, i32 damp, i32 p, i32 gre, i32 gim, i32 rs, i32 lrs, i32 rc,
                        i32& r1, i32& r0) {
    i32 y1 = 0, y2 = 0, ov = 0;
    for (unsigned n = 0; n < STEP; ++n) {
        const i32 y = (high ? osc<true>(y1, y2, c) : osc<false>(y1, y2, c)) + mul(p, STRIKE[n]);
        sum.add(acc + n, y, ov);
        y2 = y1; y1 = y;
    }
    sum.any |= ov;
    const i32 s1 = mul(y1, damp), s0 = mul(y2, damp);
    const i32 d = s0 - mul(rc, s1);
    i32 im = 0;
    if (d) {
        const u32 a = exp2u(log2u(static_cast<u32>(absolute(d))) - lrs);
        im = a > 0x3fffffffu ? 0x3fffffff : static_cast<i32>(a);
        if (d < 0) im = -im;
    }
    r1 = (mul(gre, s1) - mul(gim, im)) * 4;            // G in Q29
    r0 = mul(rc, r1) + (mul(gre, d) + mul(gim, mul(rs, s1))) * 4;
}
// A mode through the block: STEPS steps, the strike's rotated ring (r: y1, y2, or null) joining after the first. Hot or
// not is settled for the block, and again after a strike joins.
template <bool H, bool HOLD, class S>
inline void one_steps(S& sum, i32* acc, const i32* in, Mode& m, unsigned j) {
    for (; j < STEPS; ++j) one_step<H, HOLD>(sum, acc + j * STEP, in + j * (STEP / 2), m);
}
template <bool H, class S>
inline void one_block(S& sum, i32* acc, const i32* in, Mode& m, const i32* r) {
    unsigned j = 0;
    if (r) {
        if (hot<H>(m)) one_step<H, true>(sum, acc, in, m); else one_step<H, false>(sum, acc, in, m);
        m.y1 = add_sat(m.y1, r[0]); m.y2 = add_sat(m.y2, r[1]);
        j = 1;
    }
    if (hot<H>(m)) one_steps<H, true>(sum, acc, in, m, j); else one_steps<H, false>(sum, acc, in, m, j);
}
template <bool H, bool HOLD, class S>
inline void each_one_steps(S& sum, i32* acc, const i32* x, Mode& m, unsigned j) {
    for (; j < STEPS; ++j) each_one_step<H, HOLD>(sum, acc + j * STEP, x + j * STEP, m);
}
template <bool H, class S>
inline void each_one_block(S& sum, i32* acc, const i32* x, Mode& m, const i32* r) {
    unsigned j = 0;
    if (r) {
        if (hot<H>(m)) each_one_step<H, true>(sum, acc, x, m); else each_one_step<H, false>(sum, acc, x, m);
        m.y1 = add_sat(m.y1, r[0]); m.y2 = add_sat(m.y2, r[1]);
        j = 1;
    }
    if (hot<H>(m)) each_one_steps<H, true>(sum, acc, x, m, j); else each_one_steps<H, false>(sum, acc, x, m, j);
}

// Adds each mode into acc, a mode at a time through the whole block: those fed by two (in, the drive's pair sums)
// and those fed every sample (x, the drive). With STRIKE, the pulse goes into the modes during the note's first step,
// shared between the audible modes by sqrt(ra).
template <class S>
void modes_block(S& sum, Voice& v, const i32* x, const i32* in, i32* acc, bool strike) {
    i32 term[MODES], lw = 0;
    if (strike) {
        i32 wsum = 0;
        for (unsigned k = 0; k < MODES; ++k) {
            term[k] = v.edge[k] && v.wk[k] ? mul(mul(SQRT_RA[k], v.edge[k]), v.wk[k]) : 0;
            wsum += term[k] >> 3;                      // Q28
        }
        lw = wsum < 268 ? 0 : log2q(wsum, 28);
    }
    for (unsigned k = 0; k < MODES; ++k) {
        if (!v.edge[k]) continue;
        if (!v.wk[k] && !v.y1[k] && !v.y2[k]) continue;   // not fed and silent
        const bool high = (v.high >> k) & 1;
        Mode m = {v.y1[k], v.y2[k], v.mc[k], v.b[k], DAMP16[k], v.lim[k]};
        i32 rot[2] = {0, 0};                           // the strike's rotated ring
        if (strike && term[k])
            strike_step(sum, acc, high, v.mc[k], DAMP16[k], exp2q(L_BP[k] + v.lsn[k] + log2q(term[k], 31) - lw, 31),
                        v.gre[k], v.gim[k], v.sn[k], v.lsn[k], v.rc[k], rot[0], rot[1]);
        const i32* r = strike ? rot : 0;
        if ((v.pair >> k) & 1) { if (high) one_block<true>(sum, acc, in, m, r); else one_block<false>(sum, acc, in, m, r); }
        else { if (high) each_one_block<true>(sum, acc, x, m, r); else each_one_block<false>(sum, acc, x, m, r); }
        if (!v.wk[k] && absolute(m.y1) < FLUSH && absolute(m.y2) < FLUSH) m.y1 = m.y2 = 0;
        v.y1[k] = m.y1; v.y2[k] = m.y2;
    }
}

void clear(Voice& voice) {
    u32* words = reinterpret_cast<u32*>(&voice);
    for (unsigned i = 0; i < sizeof(Voice) / sizeof(u32); ++i) words[i] = 0;
}

// One sample of the band's poles, e = 16 n + 2 e1 - e2 - 4 m2 + m3 (n: its numerator, m2 = e1 (2 + a1'),
// m3 = e2 (1 - a2')), saturated where it would leave the 32-bit range (a voice struck again and again can drive it
// there) and exact everywhere else. e = 4 q + (r & 3), with r = 2 (e1 & 1) + m3 - e2 and
// q = 4 n - m2 + (e1 >> 1) + (r >> 2): r never wraps (0 < m3 / e2 <= 1), and q only far past the range (beyond four
// times it), so q says where e is.
inline i32 band(i32 n, i32 e1, i32 e2, i32 m2, i32 m3) {
    const i32 r = ((e1 & 1) << 1) + (m3 - e2);
    const u32 q = 4u * static_cast<u32>(n) - static_cast<u32>(m2) + static_cast<u32>(e1 >> 1) + static_cast<u32>(r >> 2);
    i32 e = static_cast<i32>(4u * q + static_cast<u32>(r & 3));
    if ((q ^ (q << 1)) >> 30) e = (static_cast<i32>(q) >> 31) ^ MAX;   // out of range: q's top three bits disagree
    return e;
}

// 2 u at the half-scale ceiling. The allpasses can overshoot half scale (to 1.43 times it, their paths' L1 gain), so
// 2 u saturates where it would wrap; the same as before for every u where it did not.
inline i32 ceiling2(i32 u) {
    const i32 v = static_cast<i32>(2u * static_cast<u32>(u));
    if ((v ^ u) < 0) return u < 0 ? -HALF_SCALE : HALF_SCALE;   // 2 u wrapped
    return clamp(v, -HALF_SCALE, HALF_SCALE);
}

// Taps for the machine's own tests: each stage of the last block (the voice-rate stages at 32 samples). Null in the
// device and preview builds.
struct Taps { i32 core[32], drive[32], mix[32], voice[32], out[64]; };

inline void process(Voice& v, opxy::Output output, opxy::Parameters parameters, opxy::Pitch pitch, Taps* taps) {
    // ---- knobs
    const i32 drop = knob_word(parameters[0]), ratio_word = ratio_of(knob_word(parameters[1]));
    const i32 stretch = knob_word(parameters[2]), modes = knob_word(parameters[3]);
    bool remode = false, remakeup = false;
    if (!v.knobs_seen || drop != v.knob[0]) set_drop(v, drop);
    if (!v.knobs_seen || stretch != v.knob[2]) { set_stretch(v, stretch); remode = true; }
    if (!v.knobs_seen || modes != v.knob[3]) { set_modes(v, modes); v.gx_dirty = 1; }
    if (!v.knobs_seen || ratio_word != v.knob[1]) { set_ratio(v, ratio_word); remakeup = true; }
    v.knob[0] = drop; v.knob[1] = ratio_word; v.knob[2] = stretch; v.knob[3] = modes; v.knobs_seen = 1;
    // ---- pitch: set up again when it moves more than about 3.4 cents (glide, bend, transpose)
    const u32 inc = pitch[0];
    const u32 moved = inc > v.setup_inc ? inc - v.setup_inc : v.setup_inc - inc;
    if (!v.setup_inc || moved > (v.setup_inc >> 9)) { setup_pitch(v, inc); remode = true; }
    if (remode) { setup_modes(v); remakeup = true; v.gx_dirty = 1; }
    if (remakeup) setup_makeup(v);
    for (unsigned k = 0; k < MODES; ++k) {             // make-up eases ~20 ms
        const i32 d = v.mk_target[k] - v.mk[k];
        if (!d) continue;
        v.mk[k] = absolute(d) < 256 ? v.mk_target[k] : v.mk[k] + mul(d, KK_MAKEUP);
        v.gx_dirty = 1;
    }
    if (v.gx_dirty) update_b(v);
    // ---- note-on
    const bool strike = v.note_pending != 0;
    if (strike) {
        v.note_pending = 0;
        const u32 base = pitch[0];
        if (v.sweep_oct) v.inc_prev = exp2u(log2_base(v, base) + v.sweep_oct);   // start where the drop starts
        else if (!v.inc_prev) v.inc_prev = base;
    }
    // ---- FM core and the onset, per step
    i32 x[VN], gains[VN];
    const bool shaped = v.ramping || v.gain != MAX;
    for (unsigned j = 0; j < STEPS; ++j) {
        core_step(v, x + j * STEP, pitch[2 * j * STEP], v.knob[1]);
        if (shaped) {
            const i32 e0 = v.gain, e1 = onset_step(v);
            const i32 d = half(e1) - half(e0);
            for (unsigned n = 0; n + 1 < STEP; ++n) gains[j * STEP + n] = e0 + 2 * mul(d, static_cast<i32>(n + 1) << 28);
            gains[j * STEP + STEP - 1] = e1;
            v.gain = e1;
        }
    }
    if (taps) for (unsigned n = 0; n < VN; ++n) taps->core[n] = x[n];
    if (shaped) for (unsigned n = 0; n < VN; ++n) x[n] = mul(x[n], gains[n]);
    if (taps) for (unsigned n = 0; n < VN; ++n) taps->drive[n] = x[n];
    // ---- the chain's high-pass shapes the drive (as the reference's first high-pass and presence peak do, which
    // STRIKE skips): (1 - z)^2 over its poles, near them, without its 1 / D (the band carries it). Two samples at a
    // time, giving the modes their input: the drive and its pair sums.
    i32 in[VN / 2], buf[VN + 2];
    i32* acc = buf + 2;
    {
        i32 x1 = v.chain[0], x2 = v.chain[1], p1 = v.chain[2], p2 = v.chain[3];
        const i32 c0 = v.ch_c[0], c1 = v.ch_c[1];
        for (unsigned n = 0; n < VN; n += 2) {
            // p = in - 2 x1 + x2 + 2 p1 - p2 - 2 p1 c0 + p2 c1
            const i32 i0 = x[n], i1 = x[n + 1];
            const i32 q0 = i0 + x2 - p2 + mul(p2, c1) - 2 * (x1 - p1 + mul(p1, c0));
            const i32 q1 = i1 + x1 - p1 + mul(p1, c1) - 2 * (i0 - q0 + mul(q0, c0));
            x2 = i0; x1 = i1; p2 = q0; p1 = q1;
            x[n] = q0; x[n + 1] = q1;
            in[n >> 1] = q0 + q1;
            acc[n] = 2 * q0; acc[n + 1] = 2 * q1;      // the mix is half the accumulator: core + modes / 2
        }
        v.chain[0] = x1; v.chain[1] = x2; v.chain[2] = p1; v.chain[3] = p2;
    }
    // ---- MODAL, mixed with the core
    {
        i32 y1[MODES], y2[MODES];
        for (unsigned k = 0; k < MODES; ++k) { y1[k] = v.y1[k]; y2[k] = v.y2[k]; }
        Note first = {0};
        modes_block(first, v, x, in, acc, strike);
        if (first.any < 0) {                           // a partial sum wrapped: again from the block's start, counting
            for (unsigned k = 0; k < MODES; ++k) { v.y1[k] = y1[k]; v.y2[k] = y2[k]; }
            i32 wraps[VN];
            for (unsigned n = 0; n < VN; ++n) { acc[n] = 2 * x[n]; wraps[n] = 0; }
            Count count = {0, acc, wraps};
            modes_block(count, v, x, in, acc, strike);
            for (unsigned n = 0; n < VN; ++n)
                if (wraps[n]) acc[n] = wraps[n] > 0 ? MAX : -MAX;
        }
    }
    if (taps) for (unsigned n = 0; n < VN; ++n) taps->mix[n] = half(acc[n]);
    // ---- the voice's output chain: low-pass FIR (a sample late; it also halves the accumulator), the onset's second
    // gain, the band; then to the output rate, two samples each: the half-band's allpass paths (on half the signal, for
    // headroom), then the ceiling
    buf[0] = v.fir[0]; buf[1] = v.fir[1];
    v.fir[0] = buf[VN]; v.fir[1] = buf[VN + 1];
    {   // the low-pass FIR, in place: g[n] into buf[n]
        i32 p0 = buf[0], p1 = buf[1];
        for (unsigned n = 0; n < VN; ++n) {
            const i32 p2 = buf[n + 2];
            const i32 hp = (p0 >> 1) + (p2 >> 1);
            const i32 dd = static_cast<i32>(static_cast<u32>(hp) - static_cast<u32>(p1));
            if (((hp ^ p1) & (hp ^ dd)) >= 0) buf[n] = (p1 >> 1) + (dd >> 5) + (dd >> 10);   // h = LP_FIR = 1/32 + 1/1024
            else buf[n] = (p1 >> 1) + fir_tail(hp, p1);  // dd wrapped (a full-scale mix at the top of the band)
            p0 = p1; p1 = p2;
        }
    }
    if (shaped) for (unsigned n = 0; n < VN; ++n) buf[n] = mul(buf[n], gains[n]);
    {   // the band: its numerator from g (into x, which the drive is done with), then its poles; then half, for the
        // half-band's headroom, in place
        i32 g1 = v.chain[4], g2 = v.chain[5];
        const i32 k0 = v.ch_c[2], k1 = v.ch_c[3];
        for (unsigned n = 0; n < VN; ++n) {
            const i32 g = buf[n];
            const i32 hg = g >> 1, h2 = g2 >> 1;
            x[n] = static_cast<i32>(static_cast<u32>(mul(hg - g1 + h2, k0)) + static_cast<u32>(mul(hg - h2, k1)));
            g2 = g1; g1 = g;
        }
        v.chain[4] = g1; v.chain[5] = g2;
        i32 e1 = v.chain[6], e2 = v.chain[7];
        const i32 k2 = v.ch_c[4], k3 = v.ch_c[5];
        for (unsigned n = 0; n < VN; ++n) {
            const i32 e = band(x[n], e1, e2, mul(e1, k2), mul(e2, k3));
            e2 = e1; e1 = e;
            buf[n] = clamp(e, -(1 << 30), 1 << 30) >> 1;
        }
        v.chain[6] = e1; v.chain[7] = e2;
    }
    if (taps) for (unsigned n = 0; n < VN; ++n) taps->voice[n] = buf[n] * 2;
    {   // to the output rate: the half-band's two allpass paths, then the ceiling
        i32 h0 = v.hb[0], a0 = v.hb[1], b0 = v.hb[2], a1 = v.hb[3], b1 = v.hb[4];
        for (unsigned n = 0; n < VN; ++n) {
            const i32 s0 = buf[n];
            const i32 t0 = mul(HB_IIR[0], s0 - a0) + h0, u0 = mul(HB_IIR[2], t0 - b0) + a0;
            const i32 t1 = mul(HB_IIR[1], s0 - a1) + h0, u1 = mul(HB_IIR[3], t1 - b1) + a1;
            h0 = s0; a0 = t0; b0 = u0; a1 = t1; b1 = u1;
            output[2 * n] = ceiling2(u0);
            output[2 * n + 1] = ceiling2(u1);
        }
        v.hb[0] = h0; v.hb[1] = a0; v.hb[2] = b0; v.hb[3] = a1; v.hb[4] = b1;
    }
    if (taps) for (unsigned n = 0; n < opxy::block_frames; ++n) taps->out[n] = output[n];
}
} // namespace

inline void initialize(Voice& voice, Shared&, u32) { clear(voice); }

// Each note: the oscillators and filters keep running (as in the reference); the drop, BITE and STRIKE start again,
// and the onset rises from wherever the level is (from silence on a fresh voice).
inline void start(Voice& voice, Shared&, u32) {
    voice.note_pending = 1;
    voice.sweep_j = 0;
    voice.sweep_u = 0;
    voice.bite = MAX;
    const i32 level = voice.gain == MAX ? MAX : mul(voice.gain, voice.gain);
    voice.ramping = level != MAX;
    voice.att_u = level;
    voice.att_g0 = voice.gain;
    voice.att_j = 0;
}

inline void destroy(Voice&, Shared&, u32) {}

inline void render(Voice& voice, Shared&, u32, opxy::Output output, opxy::Parameters parameters, opxy::Pitch pitch) {
    process(voice, output, parameters, pitch, static_cast<Taps*>(0));
}

} // namespace metal
